set-variable.value:
@{
      try { return context.Request.Body == null ? new JObject() : context.Request.Body.As<JObject>(preserveContent: true) ?? new JObject(); } catch { return new JObject(); }
    }

trace.message:
@{
        var request = (JObject)context.Variables["dcr-request"];
        var name = request["client_name"] == null ? "none" : (string)request["client_name"];
        return "oauth: dynamic client registration from " + name + " answered with the pre-registered public client";
      }

metadata.value:
@{
        var request = (JObject)context.Variables["dcr-request"];
        var name = request["client_name"] == null ? "none" : (string)request["client_name"];
        return name.Length == 0 ? "none" : (name.Length > 80 ? name.Substring(0, 80) : name);
      }

@{
        var request = (JObject)context.Variables["dcr-request"];
        var uris = request["redirect_uris"] as JArray;
        return uris == null || uris.Count == 0 ? "none" : string.Join(" ", uris.Select(u => (string)u));
      }

return-response.set-body:
@{
        JObject request = (JObject)context.Variables["dcr-request"];
        var redirects = request != null && request["redirect_uris"] is JArray
          ? (JArray)request["redirect_uris"]
          : new JArray("http://127.0.0.1:33418/", "https://vscode.dev/redirect");
        var response = new JObject();
        response["client_id"] = "__CLIENT_ID__";
        response["client_id_issued_at"] = DateTimeOffset.UtcNow.ToUnixTimeSeconds();
        response["client_name"] = request != null && request["client_name"] != null ? request["client_name"] : "MCP client";
        response["application_type"] = "native";
        response["redirect_uris"] = redirects;
        response["grant_types"] = new JArray("authorization_code", "refresh_token");
        response["response_types"] = new JArray("code");
        response["token_endpoint_auth_method"] = "none";
        return response.ToString();
      }
